<?php declare(strict_types=1); namespace Modules\PromptEngine\Console; use Illuminate\Console\Command; use Modules\PromptEngine\Services\PromptEngineService; final class GenerateCharacterPromptCommand extends Command { protected $signature='prompt-engine:generate {character} {--platform=gemini} {--style=museum-editorial} {--aspect-ratio=2:3} {--text-mode=editable-layout} {--save} {--json}'; protected $description='Generate an educational Chinese-character infographic prompt'; public function handle(PromptEngineService $engine):int{$r=$engine->generate(['character'=>$this->argument('character'),'platform'=>$this->option('platform'),'style'=>$this->option('style'),'aspect_ratio'=>$this->option('aspect-ratio'),'text_mode'=>$this->option('text-mode'),'save'=>$this->option('save')])->toArray();$json=json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$this->line($json?:'{}');return self::SUCCESS;} }
